GB28181-2016是一套视频监控设备与平台之间通信的协议，其通信内容主要包括设备控制、视频流传输、事件告警等。下面是一个简单的解析GB28181协议的示例代码，仅供参考。

1. 解析SIP请求头

SIP请求头包括很多字段，如请求方式、请求URI、协议版本、From、To、Call-ID等。以下是一个简单的SIP请求头解析的代码示例：

```
char* line = strtok(sip_msg, "\r\n");
while (line != NULL)
{
    if (strncasecmp(line, "SIP", 3) == 0) // SIP请求方法
    {
        sscanf(line, "%s %s %s", method, uri, version);
    }
    else if (strncasecmp(line, "From:", 5) == 0) // From字段
    {
        sscanf(line, "%*s %s", from);
    }
    else if (strncasecmp(line, "To:", 3) == 0) // To字段
    {
        sscanf(line, "%*s %s", to);
    }
    else if (strncasecmp(line, "Call-ID:", 8) == 0) // Call-ID字段
    {
        sscanf(line, "%*s %s", callid);
    }
    else if (strncasecmp(line, "CSeq:", 4) == 0) // CSeq字段
    {
        sscanf(line, "%*s %d %s", &cseq, method);
    }
    else if (strncasecmp(line, "Via:", 3) == 0) // Via字段
    {
        char* via_start = strstr(line, "Via:") + 4;
        char* via_end = strstr(line, " ");
        char via_addr[256] = {0};
        strncpy(via_addr, via_start, via_end - via_start);
        sscanf(via_addr, "%[^/]/%s", &via_ip, &via_port);
    }
    line = strtok(NULL, "\r\n");
}
```

2. 解析SDP协议头

SDP协议头包括媒体信息、传输协议、音视频编码格式等多个字段。以下是一个简单的SDP协议头解析的代码示例：

```
char* line = strtok(sdp_msg, "\r\n");
while (line != NULL)
{
    if (strncasecmp(line, "m=", 2) == 0) // 媒体信息
    {
        sscanf(line, "%*s %s %s %s", &media_type, &port, &protocol);
    }
    else if (strncasecmp(line, "a=rtpmap:", 9) == 0) // RTP编码格式
    {
        char* codec_start = strstr(line, "rtpmap:") + 7;
        char codec_info[128] = {0};
        strncpy(codec_info, codec_start, strlen(codec_start));
        sscanf(codec_info, "%d %[^/]/%d", &payload_type, &codec_name, &clock_rate);
    }
    else if (strncasecmp(line, "a=recvonly", 10) == 0) // 媒体类型
    {
        media_direction = RECV_ONLY;
    }
    else if (strncasecmp(line, "a=sendrecv", 10) == 0) // 媒体类型
    {
        media_direction = SEND_RECV;
    }
    line = strtok(NULL, "\r\n");
}
```

3. 解析H.264视频流

GB28181协议支持H.264视频编码格式的传输，其传输方式包括rtp-over-udp、rtp-over-tcp、rtp-over-http等多种方式。以下是一个简单的H.264视频流解析的代码示例：

```
while (1)
{
    nrecv = recvfrom(sock_fd, buffer, sizeof(buffer), 0, (struct sockaddr*)&addr, &addr_len);
    if (nrecv <= 0)
    {
        continue;
    }
    // 解析rtp包头
    rtp_header_t* hdr = (rtp_header_t*)buffer;
    uint8_t fmt = hdr->flags & 0x1F;
    uint16_t seq = ntohs(hdr->seq);
    uint32_t ts = ntohl(hdr->ts);
    uint32_t ssrc = ntohl(hdr->ssrc);
    // 解析NALU包头
    uint8_t nal_unit_type = buffer[RTP_HEADER_SIZE] & 0x1F;
    // 解析NALU数据
    uint8_t* nal_data = buffer + RTP_HEADER_SIZE + FU_HEADER_SIZE;
    uint32_t nal_len = nrecv - RTP_HEADER_SIZE - FU_HEADER_SIZE;
    // 解析FU包头
    if (fmt == 28) // FU-A分片模式
    {
        uint8_t position = buffer[RTP_HEADER_SIZE] & 0x80;
        uint8_t start = buffer[RTP_HEADER_SIZE + 1] & 0x80;
        if (start)
        {
            nal_unit_type = buffer[RTP_HEADER_SIZE + 1] & 0x1F;
            nal_data = buffer + RTP_HEADER_SIZE + FU_HEADER_SIZE + 1;
            nal_len = nrecv - RTP_HEADER_SIZE - FU_HEADER_SIZE - 1;
        }
    }
    process_nalu(nal_unit_type, nal_data, nal_len);
}
```

