```c
#include <stdio.h>
#include <stdlib.h>

struct TreeNode {
    int data;
    struct TreeNode* left;
    struct TreeNode* right;
};

struct QueueNode {
    struct TreeNode* treeNode;
    struct QueueNode* next;
};

struct Queue {
    struct QueueNode* front;
    struct QueueNode* rear;
};

void enqueue(struct Queue* queue, struct TreeNode* treeNode) {
    struct QueueNode* newNode = (struct QueueNode*) malloc(sizeof(struct QueueNode));
    newNode->treeNode = treeNode;
    newNode->next = NULL;
    if (queue->rear == NULL) {
        queue->front = newNode;
        queue->rear = newNode;
        return;
    }
    queue->rear->next = newNode;
    queue->rear = newNode;
}

struct TreeNode* dequeue(struct Queue* queue) {
    if (queue->front == NULL) {
        return NULL;
    }
    struct QueueNode* temp = queue->front;
    struct TreeNode* treeNode = temp->treeNode;
    queue->front = temp->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);
    return treeNode;
}

int isQueueEmpty(struct Queue* queue) {
    return queue->front == NULL;
}

int max(int a, int b) {
    return (a > b) ? a : b;
}

int max_width(struct TreeNode* root) {
    if (root == NULL) {
        return 0;
    }
    struct Queue* queue = (struct Queue*) malloc(sizeof(struct Queue));
    queue->front = NULL;
    queue->rear = NULL;
    enqueue(queue, root);
    int maxWidth = 0;
    while (!isQueueEmpty(queue)) {
        int width = 0;
        int count = 0;
        struct Queue* nextLevel = (struct Queue*) malloc(sizeof(struct Queue));
        nextLevel->front = NULL;
        nextLevel->rear = NULL;
        while (!isQueueEmpty(queue)) {
            struct TreeNode* treeNode = dequeue(queue);
            width++;
            if (treeNode->left != NULL) {
                enqueue(nextLevel, treeNode->left);
                count++;
            }
            if (treeNode->right != NULL) {
                enqueue(nextLevel, treeNode->right);
                count++;
            }
        }
        maxWidth = max(width, maxWidth);
        free(queue);
        queue = nextLevel;
    }
    return maxWidth;
}

int main() {
    struct TreeNode* root = (struct TreeNode*) malloc(sizeof(struct TreeNode));
    root->data = 8;
    root->left = (struct TreeNode*) malloc(sizeof(struct TreeNode));
    root->right = (struct TreeNode*) malloc(sizeof(struct TreeNode));
    root->left->data = 5;
    root->right->data = 10;
    root->left->left = (struct TreeNode*) malloc(sizeof(struct TreeNode));
    root->left->right = (struct TreeNode*) malloc(sizeof(struct TreeNode));
    root->right->left = NULL;
    root->right->right = NULL;
    root->left->left->data = 3;
    root->left->right->data = 7;
    root->left->left->left = NULL;
    root->left->left->right = NULL;
    root->left->right->left = NULL;
    root->left->right->right = NULL;

    printf("Max width of the tree: %d\n", max_width(root));
    return 0;
}
