五子棋是一种传统的棋类游戏，在这个简单的JavaScript五子棋示例中，我们将创建一个基本的五子棋游戏，用户可以在网页上进行游戏。

首先，创建一个HTML文件，并添加以下内容：

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>五子棋</title>
    <style>
        canvas {
            display: block;
            margin: 0 auto;
            background-color: #ffd89b;
        }
    </style>
</head>
<body>
    <canvas id="board" width="800" height="800"></canvas>
    <script src="gobang.js"></script>
</body>
</html>
```

然后，创建一个名为`gobang.js`的JavaScript文件，并添加以下代码：

```javascript
const canvas = document.getElementById("board");
const ctx = canvas.getContext("2d");

const gridSize = 40;
const gridCount = canvas.width / gridSize;

let gameData = new Array(gridCount).fill(null).map(() => new Array(gridCount).fill(null));
let currentPlayer = "black";

canvas.addEventListener("click", handleCanvasClick);

drawBoard();

function drawBoard() {
    for (let i = 0; i <= gridCount; i++) {
        ctx.moveTo(gridSize * i + 0.5, 0);
        ctx.lineTo(gridSize * i + 0.5, canvas.height);
        ctx.moveTo(0, gridSize * i + 0.5);
        ctx.lineTo(canvas.width, gridSize * i + 0.5);
    }
    ctx.strokeStyle = "#000";
    ctx.stroke();
}

function handleCanvasClick(event) {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    const row = Math.floor(y / gridSize);
    const col = Math.floor(x / gridSize);

    if (!gameData[row][col]) {
        gameData[row][col] = currentPlayer;
        drawPiece(row, col);
        if (isWin(row, col)) {
            setTimeout(() => {
                alert(`${currentPlayer} wins!`);
                location.reload();
            }, 100);
        } else {
            currentPlayer = currentPlayer === "black" ? "white" : "black";
        }
    }
}

function drawPiece(row, col) {
    const x = col * gridSize + gridSize / 2;
    const y = row * gridSize + gridSize / 2;
    const radius = gridSize * 0.35;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fillStyle = currentPlayer;
    ctx.fill();
}

function isWin(row, col) {
    const directions = [
        [1, 0], // horizontal
        [0, 1], // vertical
        [1, 1], // diagonal
        [-1, 1], // anti-diagonal
    ];

    for (let dir of directions) {
        let count = 1;
        for (let i = 1; i <= 4; i++) {
            if (
                gameData[row + dir[0] * i]?.[col + dir[1] * i] ===
                currentPlayer
            ) {
                count++;
            } else {
                break;
            }
        }
        for (let i = 1; i <= 4; i++) {
            if (
                gameData[row - dir[0] * i]?.[col - dir[1] * i] ===
                currentPlayer
            ) {
                count++;
            } else {
                break;
            }
        }
        if (count >= 5) {
            return true;
        }
    }
    return false;
}
```

这个简单的五子棋实现提供了基本的棋盘和棋子绘制功能，以及胜利条件判断。玩家只需点击棋盘进行游戏。游戏规则简单：在棋盘上连续摆放五个同样颜色的棋子即获得胜利。

To render server-side-rendered content dynamically, you can use the `fetch` function to make an HTTP request to retrieve the desired content and then update the innerHTML of the target div.

First, create an API to serve your server-side-rendered content. For this example, let's assume you have an API endpoint at `https://yourserver.com/api/ssr` that returns the render HTML.

Create a JavaScript function to fetch the server-side-rendered content and insert it into the target div:

```javascript
// Function to get SSR content and insert it into the target div
async function loadSsrContent() {
  // Fetch the server-side-rendered content from the API endpoint
  const response = await fetch('https://yourserver.com/api/ssr');

  // If the fetch is successful, update the innerHTML of the target div
  if (response.ok) {
    const ssrContent = await response.text();
    document.getElementById('ssr').innerHTML = ssrContent;
  } else {
    console.error('Error fetching SSR content:', response.status, response.statusText);
  }
}
```

When you want to load the server-side-rendered content, call this function:

```javascript
document.addEventListener('DOMContentLoaded', () => {
  // Load the SSR content when the page is loaded
  loadSsrContent();
});
```

This example will insert the server-side-rendered content fetched from `https://yourserver.com/api/ssr` into a div with the id `ssr`.

